[excluded 1 generated record file -- this machinery's own receipts and adjudication records, which are bookkeeping rather than the artifact under review: .agents/receipts/loop-budget-33.json]
diff --git a/core/scripts/__tests__/guard-decision.test.mjs b/core/scripts/__tests__/guard-decision.test.mjs
index 70e4d07..c438b64 100644
--- a/core/scripts/__tests__/guard-decision.test.mjs
+++ b/core/scripts/__tests__/guard-decision.test.mjs
@@ -1,13 +1,15 @@
 import { test } from "node:test";
 import assert from "node:assert/strict";
 import { execFileSync } from "node:child_process";
-import { cpSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync } from "node:fs";
+import { cpSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
 import { tmpdir } from "node:os";
 import { fileURLToPath } from "node:url";
 import path from "node:path";

+import { REPO_ROOT as MACHINERY_ROOT } from "../review-budget.mjs";
 import {
   decide,
+  rootForMergeTarget,
   tokenize,
   segments,
   checkCommand,
@@ -1161,3 +1163,87 @@ test("no payload script reintroduces the raw-string entry-point comparison", ()
     "compare against pathToFileURL(process.argv[1]).href -- a hand-built file:// URL silently no-ops on any path needing escaping, and a script that never runs exits 0, which PreToolUse reads as allow",
   );
 });
+
+// ---------------------------------------------------------------------------
+// Which checkout answers for a merge (#27)
+// ---------------------------------------------------------------------------
+
+function checkoutWithReceipt(repo, pr) {
+  const dir = mkdtempSync(path.join(tmpdir(), "merge-root-"));
+  mkdirSync(path.join(dir, ".agents/receipts"), { recursive: true });
+  if (repo !== null) {
+    writeFileSync(path.join(dir, ".agents/receipts", `pr-${pr}.json`), JSON.stringify({ pr, repo, verdict: "READY" }));
+  }
+  return dir;
+}
+
+const mergeInput = (owner, repo, pullNumber) => ({ owner, repo, pullNumber });
+const reg = (v) => ({ HANDBOOK_ATTACHED_ROOTS: v });
+
+test("merge routing: an unregistered foreign target falls back to the project root", () => {
+  // Which makes checkMerge produce its OWN refusal, byte-for-byte what it says
+  // today, rather than a registry-flavoured one.
+  assert.equal(rootForMergeTarget(mergeInput("Other", "Repo", 7), {}).root, MACHINERY_ROOT);
+});
+
+test("merge routing: a registered checkout whose receipt names the target answers", () => {
+  const dir = checkoutWithReceipt("Other/Repo", 7);
+  assert.equal(rootForMergeTarget(mergeInput("Other", "Repo", 7), reg(`Other/Repo=${dir}`)).root, dir);
+  rmSync(dir, { recursive: true, force: true });
+});
+
+test("merge routing: a registered checkout is SELECTED even when its receipt is wrong", () => {
+  // Selection is not authorization. Falling back here pre-empted checkMerge's
+  // own receipt-vs-target refusal, so the operator was told no receipt existed
+  // locally while the actual repair sat in the registered checkout. (Codex,
+  // PR #33 round 2.)
+  const dir = checkoutWithReceipt("Third/Party", 7);
+  assert.equal(rootForMergeTarget(mergeInput("Other", "Repo", 7), reg(`Other/Repo=${dir}`)).root, dir);
+  rmSync(dir, { recursive: true, force: true });
+});
+
+test("merge routing: and checkMerge then refuses it on the identity comparison", () => {
+  // The half that makes the above safe: selecting a wrongly-stamped checkout
+  // hands checkMerge a receipt it rejects, naming both repositories.
+  const reason = checkMerge(mergeInput("Other", "Repo", 7), {
+    readReceipt: () => ({ pr: 7, repo: "Third/Party", verdict: "READY" }),
+    resolveSha: () => "deadbeef",
+    resolveConfig: () => ({ repo: "Other/Repo", requiredChecks: ["Test"] }),
+  });
+  assert.match(reason, /minted for Third\/Party/);
+  assert.match(reason, /merge targets Other\/Repo/);
+});
+
+test("merge routing: a registered checkout with no receipt is still selected", () => {
+  // So the refusal points at the checkout the operator must actually fix.
+  const dir = checkoutWithReceipt(null, 7);
+  assert.equal(rootForMergeTarget(mergeInput("Other", "Repo", 7), reg(`Other/Repo=${dir}`)).root, dir);
+  rmSync(dir, { recursive: true, force: true });
+});
+
+test("merge routing: a malformed registry falls back rather than throwing", () => {
+  // The hook cannot afford a throw: exit 1 is read as a hook error and the
+  // tool call proceeds.
+  assert.doesNotThrow(() => rootForMergeTarget(mergeInput("Other", "Repo", 7), reg("garbage")));
+  assert.equal(rootForMergeTarget(mergeInput("Other", "Repo", 7), reg("garbage")).root, MACHINERY_ROOT);
+});
+
+test("merge routing: an input with no usable target never consults the registry", () => {
+  for (const input of [{}, { pullNumber: 7 }, { owner: "a", pullNumber: 7 }, { owner: "a", repo: "b" }]) {
+    assert.equal(rootForMergeTarget(input, reg("Other/Repo=/tmp/x")).root, MACHINERY_ROOT);
+  }
+});
+
+test("merge routing: a malformed registry is REPORTED, not silently discarded", () => {
+  // Without this, a foreign merge refused with only "no readiness receipt",
+  // so an operator would re-capture a good receipt forever while the actual
+  // cause -- a registry typo -- was never named. (Codex, PR #33 round 1.)
+  const { root, registryProblem } = rootForMergeTarget(mergeInput("Other", "Repo", 7), reg("garbage"));
+  assert.equal(root, MACHINERY_ROOT, "still fails closed");
+  assert.match(registryProblem, /not "owner\/name=\/absolute\/path"/);
+});
+
+test("merge routing: a well-formed registry reports no problem", () => {
+  const { registryProblem } = rootForMergeTarget(mergeInput("Other", "Repo", 7), reg("Some/Where=/tmp/x"));
+  assert.equal(registryProblem, null, "a valid registry that simply lacks the key is not a problem to report");
+});
diff --git a/core/scripts/__tests__/pr-ready.test.mjs b/core/scripts/__tests__/pr-ready.test.mjs
index 8a6f144..c7fa228 100644
--- a/core/scripts/__tests__/pr-ready.test.mjs
+++ b/core/scripts/__tests__/pr-ready.test.mjs
@@ -23,6 +23,7 @@ import {
   receiptIdentityReason,
   receiptPolicyReason,
   CODEX_BOT,
+  remoteTip,
 } from "../pr-ready.mjs";
 import { __resetRepoSlugCache } from "../review-budget.mjs";

@@ -2325,3 +2326,55 @@ test("a completed SECURITY review is not reported as an unreadable code review",
   const unreadable = codexEvidenceNote([codexComment("## Review Result\n\nLooks good.")], [], PR15_HEAD);
   assert.match(unreadable, /parser gap/);
 });
+
+// ---------------------------------------------------------------------------
+// remoteTip resolves the origin of the root it is GIVEN (#27, #28 round 1)
+// ---------------------------------------------------------------------------
+
+test("remoteTip resolves the given checkout's origin, not the process's", () => {
+  // THE ONE FAIL-OPEN THIS CHANGE COULD HAVE INTRODUCED. `remoteTip` took no
+  // root and shelled to `git ls-remote origin` in whatever cwd it inherited.
+  // Routing the receipt and config reads to a resolved checkout while leaving
+  // this one behind means a cross-repo merge resolves the PRIMARY repo's
+  // origin -- and a coincidentally same-named branch there yields a tip that
+  // authorizes a stale foreign head. Two real repos with the SAME branch name
+  // at DIFFERENT commits is the only fixture that can catch it.
+  const upstreamA = tempRepo();
+  const upstreamB = tempRepo();
+  const shaA = upstreamA.commit({ "a.txt": "local" }, "local");
+  const shaB = upstreamB.commit({ "b.txt": "foreign" }, "foreign");
+  assert.notEqual(shaA, shaB, "the fixture is only meaningful if the tips differ");
+
+  const localName = upstreamA.run(["rev-parse", "--abbrev-ref", "HEAD"]).trim();
+  const foreignName = upstreamB.run(["rev-parse", "--abbrev-ref", "HEAD"]).trim();
+  assert.equal(localName, foreignName, "both checkouts must share a branch name for this to bite");
+
+  const localCheckout = tempRepo();
+  const foreignCheckout = tempRepo();
+  localCheckout.run(["remote", "add", "origin", upstreamA.dir]);
+  foreignCheckout.run(["remote", "add", "origin", upstreamB.dir]);
+
+  assert.equal(remoteTip(localName, localCheckout.dir), shaA);
+  assert.equal(
+    remoteTip(foreignName, foreignCheckout.dir),
+    shaB,
+    "asking the foreign checkout must return the FOREIGN tip, never the local one",
+  );
+
+  try {
+    rmSync(upstreamA.dir, { recursive: true, force: true });
+    rmSync(upstreamB.dir, { recursive: true, force: true });
+    rmSync(localCheckout.dir, { recursive: true, force: true });
+    rmSync(foreignCheckout.dir, { recursive: true, force: true });
+  } catch {
+    // Cleanup is best-effort; a leaked temp dir must not fail the suite.
+  }
+});
+
+test("remoteTip keeps working for the direct --show caller, which passes no root", () => {
+  // Gap 5 in issue #32: `pr-ready.mjs`'s --show path calls remoteTip(branch)
+  // directly and has no unit test, so a REQUIRED root parameter would have
+  // broken it silently. The default is what keeps that caller correct.
+  assert.equal(remoteTip.length, 1, "the root parameter must be optional, so arity stays 1");
+  assert.equal(remoteTip(""), null, "the single-argument shape still behaves");
+});
diff --git a/core/scripts/__tests__/review-budget.test.mjs b/core/scripts/__tests__/review-budget.test.mjs
index f87635c..d04cec9 100644
--- a/core/scripts/__tests__/review-budget.test.mjs
+++ b/core/scripts/__tests__/review-budget.test.mjs
@@ -22,6 +22,7 @@ import {
   validateCheckReceipt,
   assertCountingSnapshot,
   judgeReviewRequest,
+  attachedRoots,
   MAX_CHECK_AGE_MS,
   repoSlug,
   declare,
@@ -2006,3 +2007,227 @@ test("an undeclared identity does NOT block calls that are not review requests",
   assert.equal(unrelated.blocked, false, "an unrelated tool must pass");
   __resetRepoSlugCache();
 });
+
+// ---------------------------------------------------------------------------
+// Cross-repo resolution: which checkout answers for a call (#27)
+// ---------------------------------------------------------------------------
+
+const FOREIGN_SLUG = "OtherOwner/OtherRepo";
+const [FOREIGN_OWNER, FOREIGN_REPO] = FOREIGN_SLUG.split("/");
+const FOREIGN_ROOT = "/checkouts/other";
+
+/** A review request aimed at a repository that is NOT the fixture identity. */
+const foreignPost = (pr, body = "@codex review") => ({
+  toolName: "mcp__github__add_issue_comment",
+  toolInput: { owner: FOREIGN_OWNER, repo: FOREIGN_REPO, issue_number: pr, body },
+});
+
+/** A checkout of FOREIGN_SLUG holding an authorized loop for `pr`. */
+const foreignIo = (pr) =>
+  fakeIo(
+    { [budgetPath(pr)]: budget(pr, "product", { repo: FOREIGN_SLUG }), [checkPath(pr)]: check(pr, 2, { repo: FOREIGN_SLUG }) },
+    { slug: FOREIGN_SLUG },
+  );
+
+const registry = (value) => ({ HANDBOOK_ATTACHED_ROOTS: value });
+const judge = (call, io, env, makeIo = () => fakeIo()) => judgeReviewRequest(call, io, NOW, { env, makeIo });
+
+// --- the registry's own contract -------------------------------------------
+
+test("an unset registry leaves a foreign target refused", () => {
+  const { blocked } = judge(foreignPost(1), fakeIo(), {});
+  assert.equal(blocked, true, "with nowhere to look, a foreign target cannot be authorized");
+});
+
+test("attachedRoots parses newline-separated entries and normalizes the root", () => {
+  const { map, problem } = attachedRoots(registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}/`));
+  assert.equal(problem, null);
+  assert.equal(map.get(FOREIGN_SLUG.toLowerCase()), FOREIGN_ROOT);
+});
+
+test("a path containing the OLD ':' delimiter is a legal root, not a parse error", () => {
+  // The first design split on the platform path delimiter, which made a real
+  // POSIX checkout at /workspace/team:archive/repo unusable. (Codex, PR #28
+  // round 3; gap 3 in issue #32.) This is the regression that keeps it fixed.
+  const weird = "/workspace/team:archive/repo";
+  const { map, problem } = attachedRoots(registry(`${FOREIGN_SLUG}=${weird}`));
+  assert.equal(problem, null, "':' is legal in a POSIX directory name and must not end an entry");
+  assert.equal(map.get(FOREIGN_SLUG.toLowerCase()), weird);
+});
+
+test("a path containing '=' survives, because only the FIRST '=' separates", () => {
+  const weird = "/checkouts/a=b/repo";
+  const { map } = attachedRoots(registry(`${FOREIGN_SLUG}=${weird}`));
+  assert.equal(map.get(FOREIGN_SLUG.toLowerCase()), weird);
+});
+
+test("a relative root is refused rather than resolved against the process cwd", () => {
+  const { map, problem } = attachedRoots(registry(`${FOREIGN_SLUG}=relative/path`));
+  assert.equal(map, null);
+  assert.match(problem, /absolute path/);
+});
+
+test("a duplicate key invalidates the variable rather than picking one", () => {
+  const { map, problem } = attachedRoots(registry(`${FOREIGN_SLUG}=/a\n${FOREIGN_SLUG}=/b`));
+  assert.equal(map, null, "a duplicate means the operator holds two beliefs; the machinery must not choose");
+  assert.match(problem, /declared more than once/);
+});
+
+test("one malformed entry invalidates the WHOLE variable, never just itself", () => {
+  // A partly-parsed registry resolves some targets and not others, which is
+  // the kind of partial success that reads as correct.
+  const { map, problem } = attachedRoots(registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}\nnot-a-slug=/x`));
+  assert.equal(map, null);
+  assert.match(problem, /not a repository slug/);
+});
+
+test("attachedRoots never throws, whatever the variable holds", () => {
+  for (const value of ["", "   ", "=", "=/x", "a/b=", "\n\n", "a/b=/x\n\n\n"]) {
+    assert.doesNotThrow(() => attachedRoots(registry(value)), `threw on ${JSON.stringify(value)}`);
+  }
+  assert.doesNotThrow(() => attachedRoots({}));
+  assert.doesNotThrow(() => attachedRoots(undefined));
+});
+
+// --- resolution ------------------------------------------------------------
+
+test("a foreign target is authorized by the REGISTERED checkout's own budget", () => {
+  const foreign = foreignIo(1);
+  const { blocked } = judge(foreignPost(1), fakeIo(), registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}`), () => foreign);
+  assert.equal(blocked, false, "the target repository's own loop authorizes the round");
+});
+
+test("the foreign path runs the SAME decision matrix, not a permissive copy", () => {
+  // Same registered checkout, but its loop is exhausted. If the foreign branch
+  // were a shortcut rather than the same judgement, this would pass.
+  const spent = fakeIo(
+    {
+      [budgetPath(1)]: budget(1, "product", { repo: FOREIGN_SLUG }),
+      [checkPath(1)]: check(1, TIERS.product.budget, { repo: FOREIGN_SLUG }),
+    },
+    { slug: FOREIGN_SLUG },
+  );
+  const { blocked } = judge(foreignPost(1), fakeIo(), registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}`), () => spent);
+  assert.equal(blocked, true, "an exhausted foreign loop must refuse exactly as a local one would");
+});
+
+test("a registered checkout whose receipt names a THIRD repository is refused, naming both", () => {
+  const impostor = fakeIo(
+    { [budgetPath(1)]: budget(1, "product", { repo: "Third/Party" }), [checkPath(1)]: check(1, 2, { repo: "Third/Party" }) },
+    { slug: "Third/Party" },
+  );
+  const { blocked, reason } = judge(foreignPost(1), fakeIo(), registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}`), () => impostor);
+  assert.equal(blocked, true, "locating is not trusting -- the receipt still has to name the target");
+  assert.match(reason, /declared for Third\/Party/, "the refusal must name what it actually found");
+  assert.match(reason, new RegExp(`targets ${FOREIGN_SLUG}`));
+});
+
+test("a registered checkout with a MALFORMED budget reports ITS error, not the project root's", () => {
+  // Selection is not authorization. Rejecting the foreign state because its
+  // budget was unusable left the operator reading the project root's unrelated
+  // "no budget declared" and repairing the wrong checkout, while the real,
+  // fixable error stayed hidden. (Codex, PR #33 round 2.)
+  const corrupt = fakeIo({ [budgetPath(1)]: "{ not json" }, { slug: FOREIGN_SLUG });
+  const { blocked, reason } = judge(foreignPost(1), fakeIo(), registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}`), () => corrupt);
+  assert.equal(blocked, true);
+  assert.match(reason, /receipt is unusable/, "the registered checkout's own diagnosis reaches the operator");
+  assert.doesNotMatch(reason, /no round budget declared/, "not the project root's unrelated complaint");
+});
+
+test("a '..' segment is refused rather than collapsed lexically", () => {
+  // POSIX resolves a symlink before applying '..'; path.normalize collapses
+  // lexically, and the two disagree. (Codex, PR #33 round 2.)
+  const { map, problem } = attachedRoots(registry(`${FOREIGN_SLUG}=/mount/current/../repo`));
+  assert.equal(map, null);
+  assert.match(problem, /"\.\." segment/);
+});
+
+test("a registered checkout holding no budget at all is refused", () => {
+  const empty = fakeIo({}, { slug: FOREIGN_SLUG });
+  const { blocked } = judge(foreignPost(1), fakeIo(), registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}`), () => empty);
+  assert.equal(blocked, true);
+});
+
+test("a registry that resolves no key for this target is refused", () => {
+  const { blocked } = judge(foreignPost(1), fakeIo(), registry(`Someone/Else=${FOREIGN_ROOT}`), () => foreignIo(1));
+  assert.equal(blocked, true);
+});
+
+// --- local parity, which is the invariant most at risk ----------------------
+
+test("an authorized LOCAL call is unaffected by a malformed registry", () => {
+  // Gap 4 in issue #32: an earlier test spec demanded a malformed registry
+  // block "every target", which would have broken authorized local work for an
+  // irrelevant environment variable.
+  const io = fakeIo({ [budgetPath(1)]: budget(1), [checkPath(1)]: check(1, 2) });
+  const { blocked } = judge(post(1), io, registry("total nonsense"));
+  assert.equal(blocked, false, "the registry is consulted only when the project root did not answer");
+});
+
+test("an authorized local call never consults the registry at all", () => {
+  const io = fakeIo({ [budgetPath(1)]: budget(1), [checkPath(1)]: check(1, 2) });
+  let consulted = false;
+  const env = new Proxy(registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}`), {
+    get(t, k) {
+      if (k === "HANDBOOK_ATTACHED_ROOTS") consulted = true;
+      return t[k];
+    },
+  });
+  judge(post(1), io, env);
+  assert.equal(consulted, false, "step 1 answered, so nothing else may be read");
+});
+
+test("a local call with no budget refuses with the message it has today", () => {
+  const withRegistry = judge(post(1), fakeIo(), registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}`)).reason;
+  const without = judge(post(1), fakeIo(), {}).reason;
+  assert.equal(withRegistry, without, "a well-formed registry changes no local refusal, byte for byte");
+  assert.match(withRegistry, /no round budget declared/);
+});
+
+test("a malformed registry adds a diagnostic sentence but never changes the verdict", () => {
+  const { blocked, reason } = judge(post(1), fakeIo(), registry("garbage"));
+  assert.equal(blocked, true);
+  assert.match(reason, /no round budget declared/, "the original refusal survives intact");
+  assert.match(reason, /HANDBOOK_ATTACHED_ROOTS could not be read/);
+});
+
+test("neither path reads the machinery config to establish identity", () => {
+  // The discriminator this design deleted would have needed one. Asserted for
+  // a local and a foreign request so it cannot creep back as an implementation
+  // convenience. (Codex, PR #28 round 1.)
+  for (const [label, call, makeIo] of [
+    ["local", post(1), () => fakeIo()],
+    ["foreign", foreignPost(1), () => foreignIo(1)],
+  ]) {
+    const reads = [];
+    const io = fakeIo({ [budgetPath(1)]: budget(1), [checkPath(1)]: check(1, 2) });
+    const watched = { ...io, read: (rel) => (reads.push(rel), io.read(rel)) };
+    judge(call, watched, registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}`), makeIo);
+    assert.equal(
+      reads.includes(MACHINERY_CONFIG_FILE),
+      false,
+      `${label}: judgeReviewRequest read ${MACHINERY_CONFIG_FILE}`,
+    );
+  }
+});
+
+test("whitespace in a checkout path is preserved, because it is legal on POSIX", () => {
+  // Trimming the whole entry rewrote such a path before any evidence was read,
+  // so a legitimately-registered checkout fell back and refused. (Codex, PR #33
+  // round 1.)
+  const padded = "/checkouts/trailing space ";
+  const { map, problem } = attachedRoots(registry(`${FOREIGN_SLUG}=${padded}`));
+  assert.equal(problem, null);
+  assert.equal(map.get(FOREIGN_SLUG.toLowerCase()), padded, "the operator's path, byte for byte");
+});
+
+test("a trailing carriage return is stripped, being a line-ending artifact", () => {
+  const { map } = attachedRoots(registry(`${FOREIGN_SLUG}=${FOREIGN_ROOT}\r`));
+  assert.equal(map.get(FOREIGN_SLUG.toLowerCase()), FOREIGN_ROOT);
+});
+
+test("leading indentation before a slug key is dropped, since a slug has no whitespace", () => {
+  const { map, problem } = attachedRoots(registry(`  ${FOREIGN_SLUG}=${FOREIGN_ROOT}`));
+  assert.equal(problem, null);
+  assert.equal(map.get(FOREIGN_SLUG.toLowerCase()), FOREIGN_ROOT);
+});
diff --git a/core/scripts/guard-decision.mjs b/core/scripts/guard-decision.mjs
index cc67b01..3f5d2c6 100644
--- a/core/scripts/guard-decision.mjs
+++ b/core/scripts/guard-decision.mjs
@@ -239,6 +239,7 @@ import {
   judgeReviewRequest,
   machineryConfig,
   nodeIo,
+  attachedRoots,
 } from "./review-budget.mjs";

 const ALLOW = 0;
@@ -1758,15 +1759,78 @@ export function checkMerge(toolInput, { now = Date.now(), readReceipt, resolveSh
   return null;
 }

-function readReceiptFromDisk(pr) {
+/**
+ * The readiness receipt for `pr`, from `root`'s WORKING TREE.
+ *
+ * Working-tree, not durable ref, and that is deliberate rather than an
+ * oversight: `.agents/receipts/.gitignore` ignores `pr-*.json`, because a
+ * readiness receipt is minted and consumed inside one close-out and a
+ * committed one would let stale evidence authorize a merge. Only budgets and
+ * extension decisions are durable. Rooting this at a resolved checkout must
+ * preserve those semantics -- reading it from a ref instead would make a
+ * freshly minted receipt invisible. (Codex, PR #28 rounds 1-2.)
+ */
+function readReceiptAt(root, pr) {
   try {
-    const file = join(REPO_ROOT, RECEIPTS_DIR, `pr-${pr}.json`);
+    const file = join(root, RECEIPTS_DIR, `pr-${pr}.json`);
     return JSON.parse(readFileSync(file, "utf8"));
   } catch {
     return null;
   }
 }

+/**
+ * Which checkout answers for a merge aimed at `toolInput`'s repository.
+ *
+ * SAME SHAPE AS THE REVIEW-REQUEST PATH: the project root is tried first with
+ * no local/foreign discriminator, a registered checkout is consulted only when
+ * the root's receipt does not name the target, and if none answers we return
+ * the project root so `checkMerge` produces its OWN refusal -- byte-for-byte
+ * what it says today.
+ *
+ * LOCATING IS NOT TRUSTING. This picks a directory; `checkMerge` still runs
+ * every check it runs now, including the receipt-vs-target comparison that a
+ * wrongly-registered root would fail. A bad entry therefore degrades to a
+ * refusal and can never manufacture an allow.
+ *
+ * TOTAL BY CONSTRUCTION. `readReceiptAt` swallows to null, `attachedRoots`
+ * cannot throw, and the path operations are pure -- required, because this
+ * runs on the hook path where an escaping exception exits 1 and lets the tool
+ * call through.
+ */
+export function rootForMergeTarget(toolInput, env = process.env) {
+  const pr = toolInput?.pullNumber;
+  const owner = toolInput?.owner;
+  const repo = toolInput?.repo;
+  if (!Number.isInteger(pr) || typeof owner !== "string" || typeof repo !== "string" || !owner || !repo) {
+    return { root: REPO_ROOT, registryProblem: null };
+  }
+  const target = `${owner}/${repo}`.toLowerCase();
+  const names = (receipt) => typeof receipt?.repo === "string" && receipt.repo.toLowerCase() === target;
+
+  if (names(readReceiptAt(REPO_ROOT, pr))) return { root: REPO_ROOT, registryProblem: null };
+
+  // THE PARSE PROBLEM IS CARRIED, NOT DISCARDED. Dropping it left a foreign
+  // merge refused with only "no readiness receipt for PR #N" -- so an operator
+  // would re-capture a perfectly good receipt in the target checkout over and
+  // over while a registry typo, the actual cause, was never named. The review
